import { cp, rm } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { resolve } from "node:path";
import { build } from "vite";

const root = fileURLToPath(new URL("../", import.meta.url));
const generated = resolve(root, ".extension-build");

await build({ configFile: resolve(root, "vite.config.ts") });

for (const page of ["index.html", "options.html", "popup.html"]) {
  await cp(resolve(generated, page), resolve(root, page));
}
// assets/ is generated by this script, so replace it as one unit.
await rm(resolve(root, "assets"), { recursive: true, force: true });
await cp(resolve(generated, "assets"), resolve(root, "assets"), { recursive: true });
await rm(generated, { recursive: true, force: true });
